pub fn vm_free_bytes(text: &[u8]) -> u64 {
    let mut psz: u64 = 16384;
    let mut i: usize = 0;
    let mut pages: u64 = 0;
    while (i < text.len()) {
        if at_is(text, i, b"page size of ") {
            let mut j: usize = (i + 13);
            let mut v: u64 = 0;
            while ((j < text.len()) && is_digit(text[(j) as usize])) {
                v = ((v * 10) + ((text[(j) as usize] - 48) as u64));
                j = (j + 1);
            }
            if (v > 0) {
                psz = v;
            }
        }
        if ((at_is(text, i, b"Pages free:") || at_is(text, i, b"Pages inactive:")) || at_is(text, i, b"Pages speculative:")) {
            let mut j: usize = i;
            while ((j < text.len()) && (text[(j) as usize] != 58)) {
                j = (j + 1);
            }
            j = (j + 1);
            while ((j < text.len()) && (text[(j) as usize] == 32)) {
                j = (j + 1);
            }
            let mut v: u64 = 0;
            while ((j < text.len()) && is_digit(text[(j) as usize])) {
                v = ((v * 10) + ((text[(j) as usize] - 48) as u64));
                j = (j + 1);
            }
            pages = (pages + v);
        }
        i = (i + 1);
    }
    return (pages * psz);
}

