pub const HP_APART: u8 = 0;

pub const HP_CURRENT: u8 = 2;

pub const HP_STORED: u8 = 1;

pub fn held_part(stored: &[u8], sn: usize, current: &[u8], cn: usize) -> u8 {
    let mut sa: usize = path_from(stored, sn);
    let mut sb: usize = path_to(stored, sa, sn);
    let mut ca: usize = path_from(current, cn);
    let mut cb: usize = path_to(current, ca, cn);
    if ((sb <= sa) || (cb <= ca)) {
        return HP_APART;
    }
    if path_within(stored, sa, sb, current, ca, cb) {
        return HP_STORED;
    }
    if path_within(current, ca, cb, stored, sa, sb) {
        return HP_CURRENT;
    }
    return HP_APART;
}

pub fn path_from(p: &[u8], n: usize) -> usize {
    let mut i: usize = 0;
    let mut moved: bool = true;
    while moved {
        moved = false;
        if ((i < n) && (p[(i) as usize] == b' ')) {
            i += 1;
            moved = true;
        }
        if ((((i + 1) < n) && (p[(i) as usize] == b'.')) && (p[((i + 1)) as usize] == b'/')) {
            i += 2;
            moved = true;
        }
        if ((i < n) && (p[(i) as usize] == b'/')) {
            i += 1;
            moved = true;
        }
    }
    return i;
}

pub fn path_to(p: &[u8], from: usize, n: usize) -> usize {
    let mut j: usize = n;
    while ((j > from) && ((p[((j - 1)) as usize] == b' ') || (p[((j - 1)) as usize] == b'/'))) {
        j -= 1;
    }
    return j;
}

pub fn path_within(inner: &[u8], ia: usize, ib: usize, outer: &[u8], oa: usize, ob: usize) -> bool {
    if (ob <= oa) {
        return false;
    }
    if ((ib - ia) < (ob - oa)) {
        return false;
    }
    let mut k: usize = 0;
    while (k < (ob - oa)) {
        if (inner[((ia + k)) as usize] != outer[((oa + k)) as usize]) {
            return false;
        }
        k += 1;
    }
    if ((ib - ia) == (ob - oa)) {
        return true;
    }
    return (inner[((ia + (ob - oa))) as usize] == b'/');
}

pub const AGING_DAYS: u32 = 14;

pub const CRITICAL_CAP: u32 = 3;

