pub fn has_region(layout: u8, preset: u8, r: u8) -> bool {
    return (region_px(layout, preset, r, 2) > region_px(layout, preset, r, 0));
}

pub fn orient(preset: u8) -> u8 {
    let w: i64 = (PRESET_W[(preset) as usize] as i64);
    if ((w * 1000) >= ((SIDE_MIN_ASPECT_PERMILLE * PRESET_H[(preset) as usize]) as i64)) {
        return ORIENT_SIDE;
    }
    return ORIENT_STACK;
}

pub fn overlap(layout: u8, preset: u8, a: u8, b: u8) -> bool {
    if ((has_region(layout, preset, a) == false) || (has_region(layout, preset, b) == false)) {
        return false;
    }
    let ax0: i32 = region_px(layout, preset, a, 0);
    let ay0: i32 = region_px(layout, preset, a, 1);
    let ax1: i32 = region_px(layout, preset, a, 2);
    let ay1: i32 = region_px(layout, preset, a, 3);
    let bx0: i32 = region_px(layout, preset, b, 0);
    let by0: i32 = region_px(layout, preset, b, 1);
    let bx1: i32 = region_px(layout, preset, b, 2);
    let by1: i32 = region_px(layout, preset, b, 3);
    return ((((ax0 < bx1) && (bx0 < ax1)) && (ay0 < by1)) && (by0 < ay1));
}

pub fn region_permille(layout: u8, o: u8, r: u8, j: i32) -> i32 {
    let lay: i32 = (layout as i32);
    let oi: i32 = (o as i32);
    let ri: i32 = (r as i32);
    let k: i32 = ((((((lay * 2) + oi) * 5) + ri) * 4) + j);
    return REGIONS[((k as usize)) as usize];
}

pub fn region_px(layout: u8, preset: u8, r: u8, j: i32) -> i32 {
    let p: i64 = (region_permille(layout, orient(preset), r, j) as i64);
    if ((j == 0) || (j == 2)) {
        return (((p * (PRESET_W[(preset) as usize] as i64)) / 1000) as i32);
    }
    return (((p * (PRESET_H[(preset) as usize] as i64)) / 1000) as i32);
}

