pub fn crosses(xi: i64, yi: i64, xj: i64, yj: i64, px: i64, py: i64) -> bool {
    if ((yi > py) == (yj > py)) {
        return false;
    }
    let lhs: i64 = ((px - xi) * (yj - yi));
    let rhs: i64 = ((xj - xi) * (py - yi));
    if (yj > yi) {
        return (lhs < rhs);
    }
    return (lhs > rhs);
}

pub fn inside(p: u32, px: i64, py: i64) -> bool {
    let mut odd: bool = false;
    let mut v: u32 = 0;
    while (v < 4) {
        let j: u32 = ((v + 3) % 4);
        if crosses(vx(p, v), vy(p, v), vx(p, j), vy(p, j), px, py) {
            odd = (odd == false);
        }
        v = (v + 1);
    }
    return odd;
}

pub fn vx(p: u32, v: u32) -> i64 {
    return QX[(((p * 4) + v)) as usize];
}

pub fn vy(p: u32, v: u32) -> i64 {
    return QY[(((p * 4) + v)) as usize];
}

