pub const TI_OPUS: u32 = 4;

pub const TI_SONNET: u32 = 3;

pub fn tier_model(pr: u32, ti: u32, out: &mut [u8]) -> usize {
    if (pr >= PROFILE_COUNT) {
        return 0;
    }
    if (ti >= TIER_COUNT) {
        return 0;
    }
    if (ti == TI_DEFAULT) {
        return csv_field(MODELS_DEFAULT.as_bytes(), pr, out);
    }
    let mut n: usize = 0;
    if (ti == TI_SONNET) {
        n = csv_field(MODELS_SONNET.as_bytes(), pr, out);
    }
    if (ti == TI_OPUS) {
        n = csv_field(MODELS_OPUS.as_bytes(), pr, out);
    }
    if ((ti == TI_HAIKU) || (ti == TI_FAST)) {
        n = csv_field(MODELS_HAIKU.as_bytes(), pr, out);
    }
    if (n > 0) {
        return n;
    }
    return csv_field(MODELS_DEFAULT.as_bytes(), pr, out);
}

pub fn digits(n: u32) -> u32 {
    let mut d: u32 = 1;
    let mut v: u32 = n;
    while (v >= 10) {
        v = (v / 10);
        d = (d + 1);
    }
    return d;
}

pub fn csv_field(list: &[u8], k: u32, out: &mut [u8]) -> usize {
    let mut idx: u32 = 0;
    let mut i: usize = 0;
    let mut n: usize = 0;
    while (i < list.len()) {
        if (list[(i) as usize] == 44) {
            idx = (idx + 1);
        } else {
            if (idx == k) {
                out[(n) as usize] = list[(i) as usize];
                n = (n + 1);
            }
        }
        i = (i + 1);
    }
    return n;
}

pub fn put_bytes(out: &mut [u8], at: usize, s: &[u8]) -> usize {
    let mut i: usize = 0;
    while (i < s.len()) {
        out[((at + i)) as usize] = s[(i) as usize];
        i = (i + 1);
    }
    return (at + s.len());
}

pub fn put_dec(out: &mut [u8], at: usize, v: u64) -> usize {
    let mut digits: u32 = 1;
    let mut t: u64 = v;
    while (t >= 10) {
        t = (t / 10);
        digits = (digits + 1);
    }
    let mut x: u64 = v;
    let mut i: u32 = digits;
    while (i > 0) {
        out[(((at + (i as usize)) - 1)) as usize] = (((x % 10) as u8) + 48);
        x = (x / 10);
        i = (i - 1);
    }
    return (at + (digits as usize));
}

